func droppedPackets(output string) int64 {
	var count int64
	for _, match := range regexp.MustCompile(`counter packets (\d+) bytes \d+ drop`).FindAllStringSubmatch(output, -1) {
		n, _ := strconv.ParseInt(match[1], 10, 64)
		count += n
	}
	return count
}

