func (v *VM) Requests() []APIRequest {
	r := []APIRequest{{"PUT", "/machine-config", Object{"vcpu_count": GuestVCPUs, "mem_size_mib": GuestRAMMiB, "smt": false}}, {"PUT", "/boot-source", Object{"kernel_image_path": v.Kernel, "boot_args": BootArgs}}, {"PUT", "/drives/rootfs", Object{"drive_id": "rootfs", "path_on_host": v.Image, "is_root_device": true, "is_read_only": false}}}
	if v.ManagedVolume != "" {
		r = append(r, APIRequest{"PUT", "/drives/" + ManagedVolumeDriveID, Object{"drive_id": ManagedVolumeDriveID, "path_on_host": v.ManagedVolume, "is_root_device": false, "is_read_only": false}})
	}
	return append(r, APIRequest{"PUT", "/actions", Object{"action_type": "InstanceStart"}})
}

vm_finish_output.text:
func (v *VM) FinishOutput() error {
	v.Output = Object{}
	var errs []error
	for _, entry := range []struct {
		name    string
		capture *BoundedOutput
	}{{"serial", v.Serial}, {"vmm", v.VMM}} {
		if entry.capture == nil {
			continue
		}
		r, e := entry.capture.Finish()
		if e != nil {
			errs = append(errs, e)
		}
		v.Output[entry.name] = r
		if entry.capture.Truncated {
			errs = append(errs, fmt.Errorf("Firecracker output log was truncated: %s", entry.name))
		}
	}
	v.Events.Add("firecracker_output_collected", Object{"output": v.Output})
	return errors.Join(errs...)
}

runner_parser.text:
func serialPayload(s string) []string {
	ls := lines(s)
	for i, line := range ls {
		if m := serialService.FindStringSubmatch(line); m != nil {
			ls[i] = m[1]
		}
	}
	return ls
}
func ParseRunnerResult(serial string, managed bool) (Object, error) {
	prefix, success := RunnerPrefix, RunnerSuccess
	stages := []string{"go-host-test", "rust-test", "runner"}
	if managed {
		prefix, success = VolumeRunnerPrefix, VolumeRunnerSuccess
		stages = []string{"go-host-test", "runner"}
	}
	var results []string
	for _, line := range serialPayload(serial) {
		if strings.HasPrefix(line, prefix) {
			results = append(results, line)
		}
	}
	if len(results) != 1 {
		return nil, fmt.Errorf("guest serial must contain exactly one terminal runner result; found %d", len(results))
	}
	r := results[0]
	if r == success {
		return Object{"status": "PASS"}, nil
	}
	m := regexp.MustCompile("^" + regexp.QuoteMeta(prefix) + `FAILED stage=([a-z0-9-]+) status=([1-9][0-9]{0,2})$`).FindStringSubmatch(r)
	if m == nil || !slices.Contains(stages, m[1]) {
		return nil, fmt.Errorf("guest serial contains a malformed runner result")
	}
	status, _ := strconv.Atoi(m[2])
	return Object{"status": "FAILED", "stage": m[1], "exit_status": status, "sentinel": r}, nil
}

guest_reads.text:
func GuestPath(root, path string) (string, error) {
	if !filepath.IsAbs(path) || slices.Contains(strings.Split(path, "/"), "..") {
		return "", fmt.Errorf("unsafe guest path: %s", path)
	}
	current := root
	parts := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for i, part := range parts {
		if part == "" {
			continue
		}
		current = filepath.Join(current, part)
		info, e := os.Lstat(current)
		if os.IsNotExist(e) {
			continue
		}
		if e != nil {
			return "", e
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return "", fmt.Errorf("guest path contains a symlink that could escape the image")
		}
		if i < len(parts)-1 && !info.IsDir() {
			return "", fmt.Errorf("guest path parent is not a directory")
		}
	}
	return filepath.Join(root, strings.TrimPrefix(path, "/")), nil
}
func ReadTextBounded(path string, maximum int64) (string, bool, error) {
	f, e := os.Open(path)
	if e != nil {
		return "", false, e
	}
	defer f.Close()
	b, e := io.ReadAll(io.LimitReader(f, maximum+1))
	if e != nil {
		return "", false, e
	}
	info, e := f.Stat()
	if e != nil {
		return "", false, e
	}
	return strings.ToValidUTF8(string(b[:min(int64(len(b)), maximum)]), "\uFFFD"), int64(len(b)) > maximum || info.Size() > maximum, nil
}
func ReadGuestRegularFile(root, path string, maximum int64) (string, bool, error) {
	host, e := GuestPath(root, path)
	if e != nil {
		return "", false, e
	}
	info, e := os.Lstat(host)
	if e != nil {
		return "", false, e
	}
	if !info.Mode().IsRegular() {
		return "", false, fmt.Errorf("guest evidence path is not a regular file")
	}
	return ReadTextBounded(host, maximum)
}

script_write.text:
func Write(t testing.TB, path string, data []byte, mode os.FileMode) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(path, mode); err != nil {
		t.Fatal(err)
	}
}

production_audit.text:
func CheckProductionAudit(audit Object) (map[string]int, error) {
	slots := object(audit["slots"])
	if integer(audit["unknownSources"]) != 0 || len(slots) != len(ProductionSlots) {
		return nil, errors.New("OCI simulator saw unknown sources or incomplete slots")
	}
	counts := map[string]int{}
	for _, slot := range ProductionSlots {
		entry := object(slots[slot])
		requests := array(entry["requests"])
		if integer(entry["overflow"]) != 0 || len(requests) == 0 {
			return nil, fmt.Errorf("%s OCI audit is empty or overflowed", slot)
		}
		imds, compute := map[string]bool{}, map[string]bool{}
		auth, storage := 0, 0
		for _, raw := range requests {
			r := object(raw)
			method, status, host := str(r["method"]), integer(r["status"]), str(r["host"])
			if r["listed"] != true || !slices.Contains([]string{"GET", "POST"}, method) || (status != 200 && status != 404) {
				return nil, fmt.Errorf("%s made a failed, write, or unlisted OCI request: %v", slot, r)
			}
			if status == 404 && host != "objectstorage.sa-saopaulo-1.oraclecloud.com" {
				return nil, fmt.Errorf("%s received an unexpected non-ledger 404: %v", slot, r)
			}
			switch host {
			case "169.254.169.254":
				uri := str(r["requestUri"])
				if !slices.Contains(IMDSPaths, uri) && !slices.Contains(OptionalIMDSPaths, uri) {
					return nil, fmt.Errorf("%s made an unexpected IMDS request: %v", slot, r)
				}
				imds[uri] = true
			case "auth.sa-saopaulo-1.oraclecloud.com":
				auth++
			case "iaas.sa-saopaulo-1.oraclecloud.com":
				compute[str(r["requestUri"])] = true
			case "objectstorage.sa-saopaulo-1.oraclecloud.com":
				storage++
			}
		}
		for _, p := range IMDSPaths {
			if !imds[p] {
				return nil, fmt.Errorf("%s did not exercise IMDS, federation, Compute, and ledger reads", slot)
			}
		}
		if auth < 1 || len(compute) < 3 || storage < 1 {
			return nil, fmt.Errorf("%s did not exercise IMDS, federation, Compute, and ledger reads", slot)
		}
		counts[slot] = len(requests)
	}
	return counts, nil
}
